{
  "decision": "ANSWER",
  "answer_text": "Under Brazilian law, specifically Article 1 of Law No. 12,506/2011 (which amends the CLT), an employee with up to one year of service is entitled to a base notice period of 30 days. The law provides for an additional 3 days of notice for each full year of service in the same company, up to a maximum total of 90 days. Since the employee has completed exactly one full year of continuous service, they are entitled to the base 30 days plus 3 additional days, resulting in a total required advance notice of 33 days.",
  "answer_type": "duration",
  "structured_fields": [
    {
      "name": "total_notice_days",
      "value": 33,
      "unit": "days",
      "scope": "dismissal_without_just_cause"
    },
    {
      "name": "base_notice_days",
      "value": 30,
      "unit": "days",
      "scope": "up_to_1_year_service"
    },
    {
      "name": "additional_days_per_year",
      "value": 3,
      "unit": "days",
      "scope": "per_full_year_of_service"
    }
  ],
  "conditions": [
    "Indefinite-term CLT contract",
    "Dismissal without just cause by employer",
    "Exactly one full year of continuous service with the same company",
    "No more favourable contractual or collective notice terms apply"
  ],
  "qualifications": [
    "The calculation assumes 'exactly one full year' implies completion of the first anniversary, triggering the +3 day increment.",
    "Maximum notice period under this rule is capped at 90 days."
  ],
  "jurisdiction": "BR",
  "cited_source_ids": [
