    {
      "name": "application_after_obstacle_removal_weeks",
      "value": 2,
      "unit": "weeks",
      "scope": "Antragstellung nach Behebung des Hindernisses"
    },
    {
      "name": "absolute_limit_months",
      "value": 6,
      "unit": "months",
