{
  "decision": "ANSWER",
  "answer_text": "O art. 10-A da CLT estabelece que o sócio retirante responde subsidiariamente pelas obrigações trabalhistas da sociedade relativas ao período em que figurou como sócio, desde que a ação seja ajuizada até dois anos depois de averbada a modificação do contrato. A responsabilidade segue a ordem de preferência: primeiro a empresa devedora, depois os sócios atuais e, por último, os sócios retirantes. A responsabilidade torna-se solidária com os demais quando ficar comprovada fraude na alteração societária decorrente da modificação do contrato.",
  "answer_type": "legal_rule_text",
  "structured_fields": [
    {
      "name": "prazo_ajuizamento_acao_socios_retirantes",
      "value": 2,
      "unit": "anos",
      "scope": "após averbação da modificação do contrato"
    },
    {
      "name": "tipo_responsabilidade_padrao",
      "value": "subsidiária",
      "unit": null,
      "scope": "obrigações trabalhistas do período como sócio"
    },
    {
      "name": "condicao_responsabilidade_solidaria",
      "value": "comprovação de fraude na alteração societária",
      "unit": null,
      "scope": "modificação do contrato"
    }
  ],
  "conditions": [
    "A ação deve ser ajuizada até dois anos depois de averbada a modificação do contrato.",
    "A responsabilidade aplica-se apenas às obrigações trabalhistas relativas ao período em que o indivíduo foi sócio.",
    "Deve ser observada a ordem de preferência: empresa devedora, sócios atuais, sócios retirantes."
  ],
  "qualifications": [
    "A responsabilidade é subsidiária por regra geral.",
    "A responsabilidade torna-se solidária se houver comprovação de fraude na alteração societária."
  ],
  "jurisdiction": "BR",
  "cited_source_ids": [
    "GHB-S-084eee365f7a5eec"
  ]
}

