  "answer_text": "In Singapore, an employee who has served an employer for a period of not less than 3 months is entitled to 7 days of paid annual leave for the first 12 months of continuous service. For every subsequent 12 months of continuous service with the same employer, the employee receives an additional one day of paid annual leave, up to a maximum of 14 days.",
  "answer_type": "multi_part",
  "structured_fields": [
    {
      "name": "minimum_service_months_for_entitlement",
      "value": 3,
      "unit": "months",
      "scope": "initial eligibility"
    },
    {
      "name": "base_annual_leave_days_first_12_months",
      "value": 7,
      "unit": "days",
      "scope": "first 12 months of continuous service"
    },
    {
      "name": "additional_leave_days_per_subsequent_year",
      "value": 1,
      "unit": "days",
      "scope": "every subsequent 12 months of continuous service"
    },
    {
      "name": "maximum_annual_leave_days",
      "value": 14,
      "unit": "days",
      "scope": "cap on total entitlement"
    }
  ],
  "conditions": [
    "Employee must have served the employer for at least 3 months.",
    "Entitlement applies to continuous service with the same employer."
  ],
  "qualifications": [
    "Leave is pro-rated in proportion to completed months of service if the year is incomplete (per Article 88A(2)).",
    "The maximum cap of 14 days applies regardless of length of service beyond the point where 14 days is reached."
  ],
  "jurisdiction": "SG",
  "cited_source_ids": [
    "GHB-S-9f2988a94c6864f1",
    "GHB-S-4c7017f79ffaa830"
  ]
}

