      "unit": null,
      "scope": "§ 17 Abs. 1 Nr. 3 KSchG"
    },
    {
      "name": "Zeitraum",
      "value": "30 Kalendertage",
      "unit": "Tage",
      "scope": "§ 17 Abs. 1 KSchG"
    },
    {
      "name": "Ausschluss_fristlose_Entlassungen",
      "value": true,
      "unit": null,
      "scope": "§ 17 Abs. 4 KSchG"
    }
  ],
  "conditions": [
    "Die Anzeige muss vor den Entlassungen erstattet werden.",
