      "name": "notice_period_days",
      "value": 30,
      "unit": "days",
      "scope": "statutory_minimum"
    }
  ],
  "conditions": [
    "Employment contract is indefinite-term under CLT",
    "Dismissal is without just cause by the employer",
    "Employee has exactly 1 year of continuous service with the same company",
    "No more favorable contractual or collective agreement terms apply"
  ],
  "qualifications": [
    "The calculation assumes 'exactly one full year' means the employee has completed 12 months but has not yet started the 13th month/year of service, thus falling within the 'up to 1 year' bracket for the base 30 days."
  ],
  "jurisdiction": "BR",
  "cited_source_ids": [
